package com.englishhero.reading.translation;
import java.util.*;import java.net.http.HttpClient;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.AfterEach;import tools.jackson.databind.JsonNode;
import static org.assertj.core.api.Assertions.*;
class PracticeSelectionIT extends SelectionTranslationHttpITSupport {
 @org.springframework.beans.factory.annotation.Autowired SelectionTranslationJobs jobs;
 JsonNode successful(java.net.http.HttpResponse<String> r){assertThat(r.statusCode()).withFailMessage(r.body()).isEqualTo(200);return json.readTree(r.body());}
 JsonNode material(HttpClient admin)throws Exception{
  var metadata=new LinkedHashMap<String,Object>();metadata.put("title","Private translation material "+UUID.randomUUID());metadata.put("titleZh","专项翻译验证");metadata.put("sourceKind","ORIGINAL");metadata.put("topic","education");metadata.put("sourceName","");metadata.put("sourceUrl","");metadata.put("usageNote","Synthetic integration only.");
  var input=new LinkedHashMap<String,Object>();input.put("requestId",UUID.randomUUID().toString());input.put("body","Quiet spaces help people read. Clear examples support careful practice.");input.put("metadata",metadata);input.put("readingType","DETAILED");input.put("questions",List.of(Map.of("key","q1","type","DETAIL","stem","What helps people read?","options",List.of("Quiet spaces","Busy roads","Loud music","Dark rooms"),"correctOption","A","explanation","The passage names quiet spaces.")));input.put("expectedLockVersion",0);
  var set=successful(call(admin,"POST","/admin/practice/material-sets",input));String path="/admin/practice/sets/"+set.path("id").asText();for(String kind:List.of("QUESTIONS","SOURCE"))set=successful(call(admin,"POST",path+"/review",Map.of("expectedLockVersion",set.path("lockVersion").asInt(),"kind",kind,"reviewed",true)));successful(call(admin,"POST",path+"/publish",Map.of("expectedLockVersion",set.path("lockVersion").asInt())));return successful(call(admin,"GET","/practice/sets/"+set.path("id").asText(),null));
 }
 @Test void privatePracticeSourceIsAuthorizedAndDoesNotBypassReadingProtection()throws Exception{
  var admin=actor(true);var user=actor(false);var other=actor(false);var set=material(admin);var attempt=successful(call(user,"POST","/practice/sets/"+set.path("id").asText()+"/attempts",Map.of("setVersionId",set.path("setVersionId").asText(),"requestId",UUID.randomUUID().toString())));var article=attempt.path("article");var input=new LinkedHashMap<String,Object>();input.put("requestId",UUID.randomUUID().toString());input.put("articleId",article.path("articleId").asText());input.put("versionId",article.path("id").asText());input.put("text","Quiet spaces help people read.");input.put("mode","TRANSLATION");input.put("practiceAttemptId",attempt.path("id").asText());String path="/reading/selection-translations";
  assertThat(call(other,"POST",path,input).statusCode()).isEqualTo(404);assertThat(call(guest(),"POST",path,input).statusCode()).isEqualTo(401);assertThat(call(user,"POST",path,input,false).statusCode()).isEqualTo(403);
  var bare=new LinkedHashMap<>(input);bare.remove("practiceAttemptId");assertThat(call(user,"POST",path,bare).statusCode()).isEqualTo(404);assertThat(call(user,"POST",path+"/reference",input).statusCode()).isEqualTo(200);
  var created=successful(call(user,"POST",path,input));assertThat(created.path("model").asText()).isEqualTo("baidu-general");jobs.completeBaidu(jobs.claim().orElseThrow(),new BaiduTranslationClient.Result("安静的空间帮助人们阅读。"));assertThat(successful(call(user,"POST",path,input)).path("id")).isEqualTo(created.path("id"));
  var forged=new LinkedHashMap<>(input);forged.put("requestId",UUID.randomUUID().toString());forged.put("text","This text is not in that material");assertThat(call(user,"POST",path,forged).statusCode()).isEqualTo(400);forged.put("text",input.get("text"));forged.put("mode","GRAMMAR");assertThat(call(user,"POST",path,forged).statusCode()).isEqualTo(400);
 }
 @AfterEach void cleanPracticeFixturesBeforeParentArticleCleanup(){if(owners.isEmpty())return;String ids=owners.stream().map(String::valueOf).collect(java.util.stream.Collectors.joining(",")),articles="SELECT id FROM reading_article WHERE created_by IN ("+ids+")",sets="SELECT id FROM practice_set WHERE article_id IN ("+articles+")";jdbc.update("DELETE FROM practice_request WHERE user_id IN ("+ids+") OR set_id IN ("+sets+")");jdbc.update("DELETE FROM practice_mistake WHERE user_id IN ("+ids+") OR set_id IN ("+sets+")");jdbc.update("DELETE a FROM practice_answer a JOIN practice_attempt t ON t.id=a.attempt_id WHERE t.user_id IN ("+ids+") OR t.set_id IN ("+sets+")");jdbc.update("UPDATE practice_attempt SET source_attempt_id=NULL WHERE user_id IN ("+ids+") OR set_id IN ("+sets+")");jdbc.update("DELETE FROM practice_attempt WHERE user_id IN ("+ids+") OR set_id IN ("+sets+")");jdbc.update("UPDATE practice_set SET published_version_id=NULL,status='DRAFT' WHERE id IN (SELECT id FROM ("+sets+") owned)");jdbc.update("DELETE FROM practice_set_version WHERE set_id IN ("+sets+")");jdbc.update("DELETE FROM practice_set WHERE article_id IN ("+articles+")");jdbc.update("DELETE q FROM reading_question q JOIN reading_quiz_version v ON v.id=q.quiz_version_id JOIN reading_quiz z ON z.id=v.quiz_id WHERE z.article_id IN ("+articles+")");jdbc.update("UPDATE reading_quiz SET published_version_id=NULL,status='DRAFT' WHERE article_id IN ("+articles+")");jdbc.update("DELETE v FROM reading_quiz_version v JOIN reading_quiz z ON z.id=v.quiz_id WHERE z.article_id IN ("+articles+")");jdbc.update("DELETE FROM reading_quiz WHERE article_id IN ("+articles+")");}
}
